Area: {}
Severity: {}
Description: {}
Instructions: {}", alert.event, alert.area, alert.severity, alert.description, alert.instructions ) } fn format_period(period: &Period) -> String { format!( "{}:
Temperature: {}°{}
Wind: {} {}
Forecast: {}", period.name, period.temperature, period.temperature_unit, period.wind_speed, period.wind_direction, period.detailed_forecast ) } /// Build a result carrying both channels. fn dual_channel_result( text: String, structured: impl Serialize, ) -> Result<CallToolResult, ErrorData> { let value = serde_json::to_value(structured).map_err(|e| { ErrorData::internal_error(format!("failed to serialize structured content: {e}"), None) })?; let mut result = CallToolResult::success(vec![ContentBlock::text(text)]); result.structured_content = Some(value); Ok(result) } dual_channel_result builds a CallToolResult whose content holds the human-readable text and whose structured_content holds the JSON that matches the tool’s output schema.

